&lt;h2&gt;


  Step 1: Set Up Shared GraphQL Schema
&lt;/h2&gt;

&lt;p&gt;
&lt;/p&gt;

&lt;p&gt;We start with a shared GraphQL schema that works across web, mobile, and server environments. This eliminates schema drift and redundant resolver logic.&lt;/p&gt;

&lt;p&gt;
&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight javascript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// shared/schema.js
// Shared GraphQL schema for cross-platform React RSC + GraphQL app
// Uses graphql/graphql-js (https://github.com/graphql/graphql-js) v16.8.1
import {
  GraphQLSchema,
  GraphQLObjectType,
  GraphQLString,
  GraphQLInt,
  GraphQLFloat,
  GraphQLList,
  GraphQLError,
  GraphQLNonNull,
} from 'graphql';

// Custom error class for consistent error handling across platforms
class ProductNotFoundError extends GraphQLError {
  constructor(productId) {
    super(`Product with ID ${productId} not found`);
    this.extensions = {
      code: 'PRODUCT_NOT_FOUND',
      productId,
      timestamp: new Date().toISOString(),
    };
  }
}

// Mock product data store (replace with database in production)
const mockProducts = [
  { id: '1', name: 'Wireless Headphones', price: 129.99, stock: 42, category: 'electronics' },
  { id: '2', name: 'Organic Cotton T-Shirt', price: 24.99, stock: 156, category: 'apparel' },
  { id: '3', name: 'Stainless Steel Water Bottle', price: 34.99, stock: 89, category: 'home' },
];

// Define Product GraphQL type with non-null constraints for required fields
const ProductType = new GraphQLObjectType({
  name: 'Product',
  description: 'E-commerce product with inventory data',
  fields: () =&amp;gt; ({
    id: { type: new GraphQLNonNull(GraphQLString), description: 'Unique product identifier' },
    name: { type: new GraphQLNonNull(GraphQLString), description: 'Display name of product' },
    price: { type: new GraphQLNonNull(GraphQLFloat), description: 'Retail price in USD' },
    stock: { type: new GraphQLNonNull(GraphQLInt), description: 'Current inventory count' },
    category: { type: new GraphQLNonNull(GraphQLString), description: 'Product category for filtering' },
  }),
});

// Root Query type with error-handling resolver logic
const RootQueryType = new GraphQLObjectType({
  name: 'Query',
  description: 'Root query type for product data',
  fields: () =&amp;gt; ({
    products: {
      type: new GraphQLNonNull(new GraphQLList(new GraphQLNonNull(ProductType))),
      description: 'Fetch all products, optionally filtered by category',
      args: {
        category: { type: GraphQLString, description: 'Optional category to filter products' },
      },
      resolve: (parent, args) =&amp;gt; {
        try {
          if (args.category) {
            const filtered = mockProducts.filter(p =&amp;gt; p.category === args.category);
            if (filtered.length === 0) {
              throw new GraphQLError(`No products found for category: ${args.category}`, {
                extensions: { code: 'CATEGORY_EMPTY', category: args.category },
              });
            }
            return filtered;
          }
          return mockProducts;
        } catch (err) {
          // Re-throw GraphQL errors directly, wrap others in generic error
          if (err instanceof GraphQLError) throw err;
          throw new GraphQLError('Failed to fetch products', {
            extensions: { code: 'FETCH_ERROR', originalError: err.message },
          });
        }
      },
    },
    product: {
      type: ProductType,
      description: 'Fetch single product by ID',
      args: {
        id: { type: new GraphQLNonNull(GraphQLString), description: 'Product ID to fetch' },
      },
      resolve: (parent, args) =&amp;gt; {
        try {
          const product = mockProducts.find(p =&amp;gt; p.id === args.id);
          if (!product) throw new ProductNotFoundError(args.id);
          return product;
        } catch (err) {
          if (err instanceof GraphQLError) throw err;
          throw new GraphQLError('Failed to fetch product', {
            extensions: { code: 'FETCH_ERROR', originalError: err.message },
          });
        }
      },
    },
  }),
});

// Export final schema for use in RSC server, Expo client, and Next.js API routes
export const schema = new GraphQLSchema({
  query: RootQueryType,
  // Mutation type omitted for brevity, add in production
});

// Validate schema on startup (only runs in Node.js environments)
if (typeof process !== 'undefined' &amp;amp;&amp;amp; process.env.NODE_ENV !== 'test') {
  try {
    // Schema validation ensures no missing required fields
    const { validateSchema } = require('graphql');
    const errors = validateSchema(schema);
    if (errors.length &amp;gt; 0) {
      console.error('Schema validation failed:', errors);
      process.exit(1);
    }
    console.log('✅ Shared GraphQL schema validated successfully');
  } catch (err) {
    console.error('Schema validation error:', err);
  }
}
&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;
&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Troubleshooting Tip:&lt;/strong&gt; If you see schema validation errors, check that all non-null fields in your type definitions have corresponding resolver returns. Missing fields in mock data will throw validation errors in Node.js environments.&lt;/p&gt;

