&lt;h2&gt;


  Step 2: React Server Components for Web (Next.js)
&lt;/h2&gt;

&lt;p&gt;
&lt;/p&gt;

&lt;p&gt;Next.js 14+ enables RSC by default. We’ll build a server-rendered product listing page that fetches GraphQL data directly on the server, with no client-side JavaScript for initial load.&lt;/p&gt;

&lt;p&gt;
&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight jsx"&gt;&lt;code&gt;&lt;span class="c1"&gt;// app/products/page.jsx
// React Server Component (RSC) for product listing page
// Uses Next.js 14.2.3 (https://github.com/vercel/next.js) with RSC enabled by default
import { graphql } from 'graphql';
import { schema } from '../../shared/schema';
import ProductCard from './ProductCard';
import ErrorBoundary from './ErrorBoundary';

// GraphQL query for product listing (executed server-side in RSC)
const PRODUCTS_QUERY = `
  query GetProducts($category: String) {
    products(category: $category) {
      id
      name
      price
      stock
      category
    }
  }
`;

// Server-side data fetching function (runs in RSC context, no client JS)
async function fetchProducts(category = null) {
  try {
    // Execute GraphQL query directly against shared schema in server context
    const result = await graphql({
      schema,
      source: PRODUCTS_QUERY,
      variableValues: { category },
      // Context for future auth/database integration
      contextValue: { user: null, db: null },
    });

    if (result.errors) {
      // Throw first GraphQL error for error boundary to catch
      throw new Error(result.errors[0].message, { cause: result.errors });
    }

    return result.data.products;
  } catch (err) {
    // Log server-side error for observability (use Sentry/DataDog in production)
    console.error('[RSC Product Fetch] Failed to fetch products:', err);
    throw new Error(`Failed to load products: ${err.message}`, { cause: err });
  }
}

// RSC default export (server-rendered, no client-side JS for initial load)
export default async function ProductsPage({ searchParams }) {
  // Extract category filter from URL search params (server-side)
  const category = searchParams?.category || null;
  let products = [];
  let error = null;

  try {
    products = await fetchProducts(category);
  } catch (err) {
    error = err;
  }

  return (


        Product Catalog
        {category &amp;amp;&amp;amp; (Filtered: {category})}


      {/* Category filter links (server-rendered, no client JS) */}


          All


          Electronics


          Apparel


          Home



      {/* Error boundary for graceful failure */}
      Failed to load products. Please try again.}&amp;gt;
        {error ? (
          Error: {error.message}
        ) : (

            {products.map(product =&amp;gt; (

            ))}

        )}


  );
}

// Generate static params for ISR (Incremental Static Regeneration) if needed
export async function generateStaticParams() {
  return ['electronics', 'apparel', 'home'].map(category =&amp;gt; ({ category }));
}

// Set revalidation period for ISR (60 seconds)
export const revalidate = 60;
&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;
&lt;/p&gt;

&lt;p&gt;&lt;strong&gt;Troubleshooting Tip:&lt;/strong&gt; If you see "window is not defined" errors, ensure you’re not importing client-side libraries (like Apollo Client) in RSC. RSC cannot access browser APIs. Use the 'use client' directive only for interactive client components.&lt;/p&gt;

