&lt;h2&gt;


  Step 3: Cross-Platform GraphQL Client for Expo
&lt;/h2&gt;

&lt;p&gt;
&lt;/p&gt;

&lt;p&gt;We’ll build a shared GraphQL client that works for Expo (iOS/Android) and Next.js client components, with retry logic and error normalization.&lt;/p&gt;

&lt;p&gt;
&lt;br&gt;
&lt;/p&gt;

&lt;div class="highlight js-code-highlight"&gt;
&lt;pre class="highlight javascript"&gt;&lt;code&gt;&lt;span class="c1"&gt;// shared/graphql-client.js
// Cross-platform GraphQL client for Expo (iOS/Android) and Next.js client components
// Uses graphql-request v6.1.0 (https://github.com/prisma/graphql-request) for lightweight fetching
import { GraphQLClient } from 'graphql-request';
import { ProductNotFoundError } from './errors';

// Environment-specific GraphQL endpoint (configured via expo-constants for mobile)
const getGraphQLEndpoint = () =&amp;gt; {
  if (typeof window !== 'undefined') {
    // Web client: use relative API route
    return '/api/graphql';
  }
  // Expo mobile: use environment variable or fallback to local dev server
  const { Constants } = require('expo-constants');
  return Constants.manifest?.extra?.graphqlEndpoint || 'http://localhost:3000/api/graphql';
};

// Initialize client with error handling and retry logic
class CrossPlatformGraphQLClient {
  constructor() {
    this.client = new GraphQLClient(getGraphQLEndpoint(), {
      headers: {
        'Content-Type': 'application/json',
      },
      // Retry failed requests (max 2 retries for network errors)
      fetch: this.retryFetch.bind(this),
    });
  }

  // Retry logic for transient network failures
  async retryFetch(url, options, retries = 2) {
    try {
      const response = await fetch(url, options);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }
      return response;
    } catch (err) {
      if (retries &amp;lt;= 0) throw err;
      console.warn(`Retrying GraphQL request (${retries} left):`, err.message);
      await new Promise(resolve =&amp;gt; setTimeout(resolve, 1000 * (3 - retries))); // Exponential backoff
      return this.retryFetch(url, options, retries - 1);
    }
  }

  // Generic request method with error normalization
  async request(query, variables = {}) {
    try {
      const data = await this.client.request(query, variables);
      return { data, error: null };
    } catch (err) {
      // Normalize GraphQL errors to consistent format
      const normalizedError = this.normalizeError(err);
      console.error('[GraphQL Client] Request failed:', normalizedError);
      return { data: null, error: normalizedError };
    }
  }

  // Normalize errors across platforms (web, iOS, Android)
  normalizeError(err) {
    if (err.response?.errors) {
      // GraphQL errors from server
      const firstError = err.response.errors[0];
      return {
        message: firstError.message,
        code: firstError.extensions?.code || 'GRAPHQL_ERROR',
        originalError: firstError,
      };
    }
    if (err instanceof ProductNotFoundError) {
      return {
        message: err.message,
        code: 'PRODUCT_NOT_FOUND',
        originalError: err,
      };
    }
    // Network or unknown errors
    return {
      message: err.message || 'Unknown error occurred',
      code: 'NETWORK_ERROR',
      originalError: err,
    };
  }
}

// Export singleton instance for shared use across platforms
export const graphqlClient = new CrossPlatformGraphQLClient();

// Example query for product details (used in both web client components and Expo screens)
export const PRODUCT_DETAIL_QUERY = `
  query GetProduct($id: String!) {
    product(id: $id) {
      id
      name
      price
      stock
      category
    }
  }
`;

// Helper function to fetch product details with error handling
export async function fetchProductDetails(productId) {
  const { data, error } = await graphqlClient.request(PRODUCT_DETAIL_QUERY, { id: productId });
  if (error) throw new Error(error.message, { cause: error });
  if (!data.product) throw new ProductNotFoundError(productId);
  return data.product;
}
&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



